function [v, crossings] = kpi_schedule_replays(crossings, ns)
%KPI_SCHEDULE_REPLAYS  The replays of the flight software's schedule: the loop counts, for each scheduled instant (ns of them), how many times
%   the time the flight software keeps passed it (from before it to at or after it); an instant passed more than once is
%   replayed (a restart sets the time back to its start, and the schedule plays again).
%   length: 64
%   crossings: inout int[*] (passed a whole number)
%   ns: int (passed a whole number)
%   returns v: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    v = 0;
    v = 0;
    for e = (0):((ns) - 1)
        if (crossings((e) + 1) > 1)
            v = (v + (crossings((e) + 1) - 1));
        end
    end
end
